window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c5948400b752539b"]={"versions": [{"id": "FIG-c5948400b752539b", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicherabbildungs- und Adressraumdiagramm im Kontext der AUTOSAR-Basissoftware (SRS Memory Hardware Abstraction Layer). Das Diagramm visualisiert die strukturelle Transformation und Abbildung von logisch fragmentierten Speicherblöcken aus einem virtuellen Adressraum auf einen kontinuierlich gepackten physikalischen NVRAM-Adressraum (Flash/EEPROM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Virtueller Adressraum (Virtual address space): Säulendarstellung mit einer Seitengröße von 64 KByte (Page size: 64 KBytes). Enthält Blöcke unterschiedlicher Größe und Belegung:</li>\n<li>Block 1: Belegtes Datensegment mit 32 Bytes (grün), gefolgt von ungenutztem Freiraum (schraffiert).</li>\n<li>Block 2: Belegtes Datensegment mit 100 Bytes (blau), gefolgt von ungenutztem Freiraum (schraffiert).</li>\n<li>Block 3: Belegtes Datensegment mit 38 Bytes (gelb), gefolgt von übrigem Adressraum (schraffiert).</li>\n<li>Physikalischer Adressraum (Physical address space): Säulendarstellung mit einer Seitengröße von 8 Bytes (Page size: 8 Bytes).</li>\n<li>Adressierungsachsen:</li>\n<li>Horizontale Achse: Blockidentifikation (Number) zur Anwahl der Blöcke.</li>\n<li>Vertikale Achse: Offset-Adressierung innerhalb der Blöcke.</li>\n<li>Zuordnungsrelationen: Gestrichelte Projektionslinien verbinden Anfangs- und Endgrenzen der Nutzdatenblöcke (32 Bytes, 100 Bytes, 38 Bytes) aus dem virtuellen Raum mit ihren Zielbereichen im physikalischen Speicher. Im physikalischen Speicher entsteht zwischen dem 100-Byte- und dem 38-Byte-Block ein schmaler Freiraum zur Ausrichtung an den physikalischen Seitengrenzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Adressumsetzung (Mapping):</p>\n<ol class=\"fig-list\">\n<li>Die übergeordnete Schicht adressiert Speichersegmente logisch über Blocknummer und relativen Block-Offset im 64-KByte-Raster.</li>\n<li>Der Memory Hardware Abstraction Layer löst die Fragmentierung auf, indem er die reinen Nutzdatenbereiche (32 Bytes, 100 Bytes, 38 Bytes) sequenziell in den physikalischen Speicher projiziert.</li>\n<li>Die physikalische Speicherung erfolgt seitenorientiert auf Basis von 8-Byte-Seiten, wobei unvermeidbare Padding- bzw. Ausrichtungsabstände (Alignments) zwischen nicht seitengleich abschließenden Datenblöcken berücksichtigt werden. Unbelegter virtueller Raum wird nicht physikalisch allokiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung der Speicherabstraktionsschicht (MemHwA, z. B. Ea/Fee):</p>\n<ul class=\"fig-list\">\n<li>Entkopplung von logischer Blockstrukturierung (virtuell 64 KByte groß) und physikalischer Speicherausnutzung.</li>\n<li>Verpflichtende Behandlung von Blockgrößen und Granularitätsunterschieden: Die Hardware-Abstraktion muss die Ausrichtung an der physikalischen Page-Größe (8 Bytes) sicherstellen.</li>\n<li>Kompaktierung: Vermeidung von Speicherverschwendung im NVRAM, indem der ungenutzte Raum zwischen virtuellen Blöcken nicht physikalisch vorgehalten wird.</li>\n</ul>"}, {"id": "FIG-7503477315c36db2", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicherabbildungs- und Adressraumdiagramm im Kontext der AUTOSAR-Basissoftware (SRS Memory Hardware Abstraction Layer). Das Diagramm visualisiert die strukturelle Transformation und Abbildung von logisch fragmentierten Speicherblöcken aus einem virtuellen Adressraum auf einen kontinuierlich gepackten physikalischen NVRAM-Adressraum (Flash/EEPROM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Virtueller Adressraum (Virtual address space): Säulendarstellung mit einer Seitengröße von 64 KByte (Page size: 64 KBytes). Enthält Blöcke unterschiedlicher Größe und Belegung:</li>\n<li>Block 1: Belegtes Datensegment mit 32 Bytes (grün), gefolgt von ungenutztem Freiraum (schraffiert).</li>\n<li>Block 2: Belegtes Datensegment mit 100 Bytes (blau), gefolgt von ungenutztem Freiraum (schraffiert).</li>\n<li>Block 3: Belegtes Datensegment mit 38 Bytes (gelb), gefolgt von übrigem Adressraum (schraffiert).</li>\n<li>Physikalischer Adressraum (Physical address space): Säulendarstellung mit einer Seitengröße von 8 Bytes (Page size: 8 Bytes).</li>\n<li>Adressierungsachsen:</li>\n<li>Horizontale Achse: Blockidentifikation (Number) zur Anwahl der Blöcke.</li>\n<li>Vertikale Achse: Offset-Adressierung innerhalb der Blöcke.</li>\n<li>Zuordnungsrelationen: Gestrichelte Projektionslinien verbinden Anfangs- und Endgrenzen der Nutzdatenblöcke (32 Bytes, 100 Bytes, 38 Bytes) aus dem virtuellen Raum mit ihren Zielbereichen im physikalischen Speicher. Im physikalischen Speicher entsteht zwischen dem 100-Byte- und dem 38-Byte-Block ein schmaler Freiraum zur Ausrichtung an den physikalischen Seitengrenzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Adressumsetzung (Mapping):</p>\n<ol class=\"fig-list\">\n<li>Die übergeordnete Schicht adressiert Speichersegmente logisch über Blocknummer und relativen Block-Offset im 64-KByte-Raster.</li>\n<li>Der Memory Hardware Abstraction Layer löst die Fragmentierung auf, indem er die reinen Nutzdatenbereiche (32 Bytes, 100 Bytes, 38 Bytes) sequenziell in den physikalischen Speicher projiziert.</li>\n<li>Die physikalische Speicherung erfolgt seitenorientiert auf Basis von 8-Byte-Seiten, wobei unvermeidbare Padding- bzw. Ausrichtungsabstände (Alignments) zwischen nicht seitengleich abschließenden Datenblöcken berücksichtigt werden. Unbelegter virtueller Raum wird nicht physikalisch allokiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung der Speicherabstraktionsschicht (MemHwA, z. B. Ea/Fee):</p>\n<ul class=\"fig-list\">\n<li>Entkopplung von logischer Blockstrukturierung (virtuell 64 KByte groß) und physikalischer Speicherausnutzung.</li>\n<li>Verpflichtende Behandlung von Blockgrößen und Granularitätsunterschieden: Die Hardware-Abstraktion muss die Ausrichtung an der physikalischen Page-Größe (8 Bytes) sicherstellen.</li>\n<li>Kompaktierung: Vermeidung von Speicherverschwendung im NVRAM, indem der ungenutzte Raum zwischen virtuellen Blöcken nicht physikalisch vorgehalten wird.</li>\n</ul>"}, {"id": "FIG-ad383c1f19efc427", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicherabbildungs- und Adressraumdiagramm im Kontext der AUTOSAR-Basissoftware (SRS Memory Hardware Abstraction Layer). Das Diagramm visualisiert die strukturelle Transformation und Abbildung von logisch fragmentierten Speicherblöcken aus einem virtuellen Adressraum auf einen kontinuierlich gepackten physikalischen NVRAM-Adressraum (Flash/EEPROM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Virtueller Adressraum (Virtual address space): Säulendarstellung mit einer Seitengröße von 64 KByte (Page size: 64 KBytes). Enthält Blöcke unterschiedlicher Größe und Belegung:</li>\n<li>Block 1: Belegtes Datensegment mit 32 Bytes (grün), gefolgt von ungenutztem Freiraum (schraffiert).</li>\n<li>Block 2: Belegtes Datensegment mit 100 Bytes (blau), gefolgt von ungenutztem Freiraum (schraffiert).</li>\n<li>Block 3: Belegtes Datensegment mit 38 Bytes (gelb), gefolgt von übrigem Adressraum (schraffiert).</li>\n<li>Physikalischer Adressraum (Physical address space): Säulendarstellung mit einer Seitengröße von 8 Bytes (Page size: 8 Bytes).</li>\n<li>Adressierungsachsen:</li>\n<li>Horizontale Achse: Blockidentifikation (Number) zur Anwahl der Blöcke.</li>\n<li>Vertikale Achse: Offset-Adressierung innerhalb der Blöcke.</li>\n<li>Zuordnungsrelationen: Gestrichelte Projektionslinien verbinden Anfangs- und Endgrenzen der Nutzdatenblöcke (32 Bytes, 100 Bytes, 38 Bytes) aus dem virtuellen Raum mit ihren Zielbereichen im physikalischen Speicher. Im physikalischen Speicher entsteht zwischen dem 100-Byte- und dem 38-Byte-Block ein schmaler Freiraum zur Ausrichtung an den physikalischen Seitengrenzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Adressumsetzung (Mapping):</p>\n<ol class=\"fig-list\">\n<li>Die übergeordnete Schicht adressiert Speichersegmente logisch über Blocknummer und relativen Block-Offset im 64-KByte-Raster.</li>\n<li>Der Memory Hardware Abstraction Layer löst die Fragmentierung auf, indem er die reinen Nutzdatenbereiche (32 Bytes, 100 Bytes, 38 Bytes) sequenziell in den physikalischen Speicher projiziert.</li>\n<li>Die physikalische Speicherung erfolgt seitenorientiert auf Basis von 8-Byte-Seiten, wobei unvermeidbare Padding- bzw. Ausrichtungsabstände (Alignments) zwischen nicht seitengleich abschließenden Datenblöcken berücksichtigt werden. Unbelegter virtueller Raum wird nicht physikalisch allokiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung der Speicherabstraktionsschicht (MemHwA, z. B. Ea/Fee):</p>\n<ul class=\"fig-list\">\n<li>Entkopplung von logischer Blockstrukturierung (virtuell 64 KByte groß) und physikalischer Speicherausnutzung.</li>\n<li>Verpflichtende Behandlung von Blockgrößen und Granularitätsunterschieden: Die Hardware-Abstraktion muss die Ausrichtung an der physikalischen Page-Größe (8 Bytes) sicherstellen.</li>\n<li>Kompaktierung: Vermeidung von Speicherverschwendung im NVRAM, indem der ungenutzte Raum zwischen virtuellen Blöcken nicht physikalisch vorgehalten wird.</li>\n</ul>"}, {"id": "FIG-9325eaae346692ed", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Speicherabbildungs- und Adressraumdiagramm im Kontext der AUTOSAR-Basissoftware (SRS Memory Hardware Abstraction Layer). Das Diagramm visualisiert die Spezifikation der Adressumsetzung von virtuellen Adressen auf physikalische Adressen eines NVRAM-Speichergeräts inklusive expliziter Bitbreiten der Adressierungskomponenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Virtueller Adressraum (Virtual address space): Säulendarstellung mit expliziter Auszeichnung „Page size: 64 KBytes“.</li>\n<li>16-Bit-Blocknummer („16 Bit Block Number“): Horizontale Adressierungskomponente zur Selektion der virtuellen Speicherblöcke (Block 1, Block 2, Block 3).</li>\n<li>16-Bit-Block-Offset („16 Bit Block Offset“): Vertikale Adressierungskomponente zur Adressierung von Offsets innerhalb eines Blocks.</li>\n<li>Enthält Block 1 (32 Bytes Nutzdaten, grün), Block 2 (100 Bytes Nutzdaten, blau) und Block 3 (38 Bytes Nutzdaten, gelb), jeweils eingebettet in schraffierte ungenutzte Adressbereiche.</li>\n<li>Physikalischer Adressraum (Physical address space): Säulendarstellung mit expliziter Auszeichnung „Page size: 8 Bytes“. Nimmt die Nutzdatenblöcke (32 Bytes, 100 Bytes, 38 Bytes) kompakt auf, ergänzt um seitenausrichtungsbedingtes Padding und rechte Textspaltenhinweise zur internen Blocknutzung.</li>\n<li>Abbildungsbeziehungen: Gestrichelte Linien kennzeichnen die Umsetzungsvektoren der jeweiligen Blockgrenzen vom virtuellen in den physikalischen Speicherbereich.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer und dynamischer Mapping-Ablauf:</p>\n<ol class=\"fig-list\">\n<li>Eine 32-Bit-Zugriffsadresse teilt sich explizit in eine 16-Bit-Blocknummer und einen 16-Bit-Block-Offset auf.</li>\n<li>Anhand der 16-Bit-Blocknummer wird der logische Block (Block 1, 2 oder 3) identifiziert; der 16-Bit-Block-Offset adressiert die Datenbytes innerhalb des maximal 64 KByte großen virtuellen Blockraums.</li>\n<li>Der Abstraction Layer setzt die Zugriffe auf den kontinuierlichen physikalischen Speicher um, wobei die Nutzdaten auf Vielfache der physikalischen Page-Größe (8 Bytes) ausgerichtet werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Direkte normative Vorgaben für Adressierungs- und Treiberarchitektur:</p>\n<ul class=\"fig-list\">\n<li>Festlegung der Adressdekodierung auf eine 16-Bit-Blocknummer und einen 16-Bit-Block-Offset (32-Bit-Adressraumstruktur für NVRAM-Manager- und MemIf-Zugriffe).</li>\n<li>Vorgabe der maximalen virtuellen Blockgröße von 64 KByte durch den 16-Bit-Offset.</li>\n<li>Vorgabe der physikalischen Zielstruktur mit 8-Byte-Page-Alignment für NVRAM-Treiber (z. B. Fls/Eep) zur Vermeidung von Write-Buffer- und Adressierungsüberläufen.</li>\n</ul>"}], "trans": [{"from": "FIG-c5948400b752539b", "to": "FIG-7503477315c36db2", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7503477315c36db2", "to": "FIG-ad383c1f19efc427", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ad383c1f19efc427", "to": "FIG-9325eaae346692ed", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Adressierungsparameter: Ergänzung der Bezeichner „16 Bit Block Number“ (horizontale Dimension) und „16 Bit Block Offset“ (vertikale Adressierungsdimension am virtuellen Adressraum).</li>\n<li>Spaltenüberschriften: Vollständige Einblendung der Bezeichner „Virtual address space / Page size: 64 KBytes“ und „Physical address space / Page size: 8 Bytes“ oberhalb der Adresssäulen (zuvor am oberen Bildrand abgeschnitten).</li>\n<li>Textanmerkungen: Ergänzung von Hinweistexten am rechten Rand des physikalischen Adressraums zur internen Blocknutzung („Block ... uses ... inter...“).</li>\n</ul>"}]};
